            for (Entry<UUID, Set<UUID>> entry : clientToFilesMap.entrySet()) {
                Set<UUID> originSet = entry.getValue();
                Set<UUID> copySet;
                synchronized (originSet) {
                     copySet = Sets.newHashSet(originSet);
